// Each entry is one connected argument: need -> behavior -> tension -> strategy.
// @who / @own are rendered for the chosen audience; scenes are examples, not reported events.
export const STORIES=[
 {id:'meaning-with-action',when:[['meaning_seeking','high'],['execution_speed','high']],thesis:'배울 이유가 분명해지면 빠르게 시도하며 이해를 넓힙니다',
 opening:'@who은 공부의 이유를 납득하려는 마음과, 결정한 일을 행동으로 옮기는 속도를 함께 갖고 있습니다. 무엇을 위해 배우는지가 연결되면 오래 준비하기보다 직접 해 보며 이해를 확인합니다.',
 mechanism:'여기서 중요한 차이는 의미를 찾는 시간이 곧 느린 시작을 뜻하지 않는다는 점입니다. 목적을 확인하는 단계와 실제 시도하는 단계가 이어지면 질문은 행동을 막는 문턱이 아니라 다음 시도의 방향이 됩니다. 배우는 이유를 먼저 연결하고 바로 작은 과제로 넘어가는 순서가 잘 맞습니다.',
 scene:'새로운 공식을 배울 때 어디에 쓰이는지 예시를 먼저 본 뒤, 비슷한 문제 하나에 곧바로 적용하는 장면입니다. 풀이가 끝난 다음 왜 그 방법이 통했는지 설명하면 시도의 속도와 이해의 깊이가 함께 남습니다.',
 trap:'처음의 목적만 확인하고 바로 다음 과제로 넘어가면 이번 시도에서 무엇을 이해했는지 놓칠 수 있습니다. 행동 뒤에 이유를 되짚는 짧은 마무리를 두세요.',action:'공부할 이유 한 줄을 적고 예제 하나를 바로 풀어 보세요. 끝나면 사용한 방법이 통하는 조건을 한 문장으로 설명하세요.',childAction:'아이에게 이번 활동으로 알아볼 것을 하나 알려 준 뒤 바로 해 보게 해 주세요. 끝나면 무엇 때문에 그렇게 되었는지 자기 말로 설명하게 해 주세요.',observe:'빨리 시작했는지와 함께, 끝난 뒤 방법의 이유를 설명할 수 있는지 확인하세요.',strong:['meaning_seeking','execution_speed'],stages:['시작','이해','마무리']},
 {id:'analysis-with-planning',when:[['analytical','high'],['planning','high']],thesis:'문제를 나누고 순서를 세울 때 복잡한 배움이 정리됩니다',
 opening:'@who은 문제의 구조를 나누어 살피고, 어떤 순서로 접근할지 정할 때 생각이 정돈됩니다. 해야 할 일이 많아 보여도 서로 다른 부분의 역할을 구분하면 첫 행동이 선명해집니다.',
 mechanism:'구조를 보는 성향은 무엇을 확인할지 정하고, 계획하는 성향은 그 확인을 어떤 순서로 진행할지 정합니다. 두 힘이 이어지면 막연한 과제가 다룰 수 있는 단계로 바뀝니다. 다만 정리한 순서가 실제 문제에도 통하는지는 별도로 확인해야 합니다.',
 scene:'긴 지문이나 복잡한 문제를 만났을 때 조건·질문·필요한 개념을 나누어 적고 첫 단계부터 적용해 보는 장면입니다. 예상과 다른 조건이 나오면 계획 전체를 버리기보다 어느 단계만 수정하면 되는지 찾아보세요.',
 trap:'잘 정리된 계획과 실제로 풀리는 방법은 같지 않을 때가 있습니다. 계획을 더 정교하게 만드는 것만으로 막힘을 해결하려 하지 말고, 실제 풀이에서 멈춘 단계로 돌아가세요.',action:'문제의 조건과 구할 것을 먼저 나누고 세 단계 이내로 순서를 적으세요. 한 번 실행한 뒤 실제로 막힌 단계 하나만 수정하세요.',childAction:'아이와 해야 할 것을 작은 단계로 나누어 적어 주세요. 한 번 해 본 뒤 어디에서 순서가 달라졌는지 물어보고, 그 단계만 함께 바꿔 주세요.',observe:'계획표의 완성도보다 정한 순서가 실제 과제를 해결하는 데 어떻게 쓰였는지 확인하세요.',strong:['analytical','planning'],stages:['시작','이해','실전']},
 {id:'quick-start-slow-finish',when:[['execution_speed','high'],['persistence','low']],thesis:'빠른 첫 시도를 다음 시도로 이어 주는 장치가 필요합니다',
 opening:'@who은 결정한 일을 행동으로 옮기는 데 힘을 씁니다. 새 과제를 만났을 때 첫 식이나 초안을 빠르게 만들며 길을 찾습니다. 다만 첫 시도를 여는 힘과 흥미가 줄어든 뒤에도 이어 가는 힘은 서로 다르게 움직입니다.',
 mechanism:'시작의 속도만 보고 긴 과제도 같은 기세로 끝낼 수 있다고 기대하면 중간의 공백을 놓칩니다. 한 번에 오래 밀어붙이는 계획보다 작은 결과를 남기고 다시 돌아올 위치를 정하는 방식이 흐름을 잇습니다.',
 scene:'새 교재의 첫 부분은 빠르게 풀지만 낯섦이 사라진 뒤 손이 덜 가는 상황을 떠올려 보세요. 멈출 때 다음 문제와 첫 행동을 표시해 두면 다시 시작할 때 무엇부터 할지 정하는 부담이 줄어듭니다.',
 trap:'처음 시작할 때의 의욕을 다음 시간에도 그대로 기대하는 지점입니다. 의욕의 크기보다 다시 돌아올 위치를 남기는 것이 중요합니다.',action:'짧은 과제 하나를 끝낸 뒤 다음에 시작할 문제와 첫 행동을 표시하세요. 다음 공부는 그 표시에서 바로 이어 가세요.',childAction:'한 활동을 마치면 다음에 해 볼 것 하나를 아이가 고르게 해 주세요. 다음 시간에는 새로운 지시를 늘리기보다 그 약속에서 시작해 주세요.',observe:'한 번에 얼마나 많이 했는지보다 멈췄다가 돌아온 횟수와 이어 간 결과를 살펴보세요.',strong:['execution_speed'],stages:['시작','연습','마무리']},
 {id:'achievement-and-evaluation',when:[['achievement','high'],['evaluation_sensitivity','high']],thesis:'성과를 향한 힘이 다른 사람의 시선에 흔들리지 않도록 중심을 잡으세요',
 opening:'@who은 목표를 이루었다는 감각에서 공부할 이유를 얻습니다. 동시에 다른 사람의 반응과 평가도 마음에 크게 들어옵니다. 내가 나아졌다는 감각과 남에게 어떻게 보이는지가 함께 움직이는 구조입니다.',
 mechanism:'비교가 목표를 선명하게 해 주기도 하지만, 비교 대상이 바뀔 때마다 계획까지 흔들리면 필요한 연습을 놓칩니다. 외부 평가는 현재 위치를 확인하는 자료로 두고, 오늘 개선할 행동은 자기 과제에서 찾아야 합니다.',
 scene:'주변의 진도나 점수를 본 뒤 아직 필요한 복습을 건너뛰고 더 어려운 문제로 넘어가고 싶어지는 상황입니다. 이때 지난번 풀지 못했던 문제로 돌아가 달라진 한 단계를 확인하면 성취의 기준이 다시 자기 공부 안으로 들어옵니다.',
 trap:'다른 사람에게 보여 주기 좋은 결과를 고르느라 지금 필요한 연습을 미루는 지점입니다. 부족한 부분을 드러내도 되는 연습 자리가 필요합니다.',action:'비교 자료를 보기 전에 어제 어려웠던 문제 하나를 다시 다루세요. 오늘 바꾼 풀이 한 단계를 기록한 뒤 전체 진도를 점검하세요.',childAction:'다른 아이와의 비교보다 지난번 아이가 어려워한 활동을 다시 펼쳐 주세요. 이번에는 어떤 도움 없이 해냈는지 구체적으로 짚어 주세요.',observe:'칭찬이나 점수가 없는 날에도 스스로 알아차린 개선점이 남는지 살펴보세요.',strong:['achievement'],stages:['동기','연습','회복']},

 {id:'understand-before-start',when:[['meaning_seeking','high'],['execution_speed','low']],thesis:'납득이 깊어질수록 힘이 생기지만, 시작의 문턱도 높아집니다',
 opening:'@who은 왜 배우는지와 어떻게 성립하는지를 알아야 마음이 움직입니다. 설명을 들을 때도 결론만 챙기기보다, 그 결론이 자기 생각과 맞물리는지 확인합니다. 이해가 자리를 잡으면 배움에 이유가 생기지만, 그 과정을 모두 끝낸 뒤 움직이려 하면 첫 시도가 뒤로 밀립니다.',
 mechanism:'이 구조의 중심에는 이해하려는 욕구와 행동을 시작하는 속도의 차이가 있습니다. 아직 질문이 남아 있다는 사실을 준비가 덜 됐다는 신호로 받아들이면, 자료를 더 읽는 시간이 실제로 해 보는 시간을 대신합니다. 깊이 이해하려는 힘을 살리면서도, 작은 시도를 통해 이해가 완성되는 경험이 필요합니다.',
 scene:'새 개념을 배울 때 정의를 읽고 예시를 확인한 다음에도 “그런데 이 경우에는?”이라는 질문에서 오래 머무는 장면을 떠올려 보세요. 이때 첫 예제 하나를 직접 다뤄 보면, 읽을 때는 막연했던 질문이 구체적으로 바뀝니다. 시작은 이해를 마친 뒤 받는 허락이 아니라 이해를 만드는 한 단계입니다.',
 trap:'설명과 준비의 끝을 먼저 찾으면 첫 풀이가 늦어집니다. 질문이 있다는 사실과 지금 한 번 시도할 수 있는지를 나누어 보는 것이 전환점입니다.',
 action:'설명을 한 번 읽은 뒤 예제 하나를 먼저 풀고, 막힌 부분에서 질문 한 개를 적으세요. 추가 자료는 그 질문에 답하는 데 필요한 만큼만 확인한 뒤 같은 예제로 돌아오세요.',childAction:'설명을 마친 뒤 예제 하나를 함께 펼쳐 주세요. 아이가 막힌 지점에서 질문 한 개를 고르게 하고, 답을 확인한 다음 같은 예제를 다시 해 보게 해 주세요.',
 observe:'다음 공부에서는 준비한 시간보다 첫 시도까지 걸린 시간과, 시도 뒤 질문이 얼마나 구체적으로 바뀌었는지를 살펴보세요.',strong:['meaning_seeking'],stages:['시작','이해','실전']},
 {id:'depth-before-start',when:[['depth_orientation','high'],['execution_speed','low']],thesis:'깊이 파고드는 힘에, 첫 결과물을 만드는 순서를 더하세요',
 opening:'@who은 한 주제의 안쪽까지 들어가 자기 답을 만드는 데 마음을 씁니다. 빨리 훑고 넘어가는 것보다 충분히 생각할 시간이 있을 때 배움의 밀도가 높아집니다. 다만 생각이 정리되는 속도와 결과물을 만드는 속도 사이에는 간격이 생깁니다.',
 mechanism:'관심을 오래 붙잡는 힘이 시작 전 준비에만 쓰이면, 많이 생각했는데 남은 결과는 적다는 답답함으로 이어집니다. 모든 생각을 정리한 뒤 표현하려 하기보다, 작은 초안을 먼저 만들고 그 위에서 깊이를 더하는 순서가 이 간격을 줄입니다.',
 scene:'글을 쓰기 전 자료를 계속 읽거나 문제를 풀기 전 여러 풀이를 비교하는 상황을 떠올려 보세요. 처음부터 완성된 답을 찾는 대신 첫 문장이나 첫 식을 남겨 두면, 다음 탐색이 무엇을 보완해야 하는지 분명해집니다.',
 trap:'자료와 생각이 쌓이는 동안 실제로 만든 결과물이 뒤로 밀리는 지점입니다. 탐구를 끝낼 기준이 없으면 마무리가 계속 다음 시간으로 넘어갑니다.',action:'자료를 더 찾기 전에 첫 풀이 또는 세 문장짜리 초안을 만드세요. 이후 탐색은 그 초안에서 비어 있는 한 부분을 채우는 데 사용하세요.',childAction:'아이가 아는 만큼 먼저 말하거나 그려 보게 해 주세요. 그 결과물에서 더 알고 싶은 부분을 하나 골라 함께 찾아보고 다시 보완하게 해 주세요.',observe:'생각의 양보다 처음 만든 결과물과 수정한 결과물 사이에 무엇이 더해졌는지 비교해 보세요.',strong:['depth_orientation'],stages:['시작','표현','마무리']},
 {id:'autonomy-with-boundaries',when:[['independence','high'],['uncertainty_tolerance','low']],thesis:'스스로 결정할 자유와 분명한 출발점이 함께 필요합니다',
 opening:'@who은 중요한 선택에서 자기 판단을 남기려 합니다. 그렇다고 아무 방향 없이 모든 것을 맡겨 두는 환경이 편한 것은 아닙니다. 원하는 것은 방법을 고를 자유이지, 무엇을 해야 하는지조차 혼자 찾아야 하는 막막함은 아닙니다.',
 mechanism:'자율성을 지키려는 마음과 불확실한 상황을 부담스러워하는 성향이 함께 움직입니다. 익숙한 과제에서는 스스로 방식을 정하지만, 처음 보는 과제에서는 목표와 끝나는 기준을 먼저 확인하려 합니다. 기준을 묻는 행동을 주도성이 없다는 뜻으로 읽으면 필요한 도움의 방향이 어긋납니다.',
 scene:'“알아서 해 봐”라는 말 앞에서는 오래 망설이다가, 방법을 하나하나 정해 주면 다시 답답해지는 상황을 생각해 보세요. “이 두 과제 중 하나를 마치면 끝”이라고 경계를 정하면 무엇을 선택하고 책임질지 선명해집니다.',
 trap:'방향이 모호한 방임과 과정까지 정하는 간섭 사이에서 에너지가 소모됩니다. 결과의 기준과 접근 방법을 나누어야 합니다.',action:'오늘 마칠 결과 한 가지를 적고, 순서와 도구는 직접 고르세요. 막히면 모든 과정을 바꾸기보다 끝나는 기준부터 다시 확인하세요.',childAction:'끝낼 과제와 마무리 기준만 함께 정해 주세요. 아이가 순서와 도구를 고르게 하고, 중간에는 지시보다 도움이 필요한 지점을 물어봐 주세요.',observe:'선택권을 주었을 때와 끝나는 기준까지 함께 주었을 때, 시작하는 모습이 어떻게 달라지는지 비교하세요.',strong:['independence'],stages:['시작','이해','마무리']},
 {id:'exploration-needs-variation',when:[['exploration','high'],['repetition_tolerance','low']],thesis:'새로운 연결에서 살아나는 집중을 반복 학습까지 이어 주세요',
 opening:'@who은 이미 아는 것에서 새로운 질문을 발견할 때 배움에 힘이 붙습니다. 같은 개념이라도 예시나 관점이 달라지면 다시 들여다볼 이유가 생깁니다. 반대로 형식과 답의 패턴이 익숙해지면 연습을 계속해야 할 이유가 흐려집니다.',
 mechanism:'새로움을 찾는 힘과 같은 활동을 견디는 힘이 서로 다른 방향을 향합니다. 탐색할 때의 몰입만 보고 반복 연습도 같은 방식으로 오래 할 수 있다고 기대하면 공부의 흐름을 놓칩니다. 반복의 목표는 유지하되, 확인하는 방법에 작은 변화를 넣어야 합니다.',
 scene:'비슷한 문제를 연달아 풀 때보다 한 문제를 풀고 “조건을 바꾸면?”이라고 묻는 장면에서 생각이 다시 움직입니다. 이때 새 단원으로 계속 넘어가는 대신 같은 개념을 설명하기·비교하기·적용하기로 바꾸면 탐색과 복습이 만납니다.',
 trap:'흥미가 줄 때마다 자료나 단원을 바꾸면 시작한 것은 많아도 익숙해질 만큼 연습한 것은 적어집니다. 새로움은 내용의 이동보다 연습 방식의 변화에 쓰는 편이 좋습니다.',action:'같은 개념으로 풀이 두 번, 설명 한 번, 조건 바꾸기 한 번을 묶으세요. 네 활동이 끝난 뒤 다음 주제로 넘어가세요.',childAction:'같은 개념을 문제·말·그림으로 번갈아 다뤄 주세요. 새로운 질문은 따로 적어 두고, 약속한 활동을 마친 뒤 하나를 함께 찾아보세요.',observe:'자료를 바꾼 횟수보다 같은 개념을 서로 다른 방식으로 얼마나 다시 다뤘는지 확인하세요.',strong:['exploration'],stages:['이해','연습','마무리']},
 {id:'achievement-under-pressure',when:[['achievement','high'],['pressure_sensitivity','high']],thesis:'잘하고 싶은 마음이 클수록 연습과 평가를 나눠야 합니다',
 opening:'@who에게 목표 달성은 공부를 움직이는 중요한 동력입니다. 노력의 결과가 보이면 다음 단계로 나아갈 이유가 생깁니다. 그런데 성과를 내야 한다는 요구가 가까워질수록, 문제를 배우는 일과 자신을 증명하는 일이 한데 엉킵니다.',
 mechanism:'성취를 원하는 마음이 압박을 만났을 때 배움보다 실패를 피하는 데 주의가 쏠리는 구조입니다. 목표를 더 크게 강조하는 것만으로는 이 긴장이 풀리지 않습니다. 틀리며 방법을 만드는 시간과 지금의 실력을 확인하는 시간을 구분해야 두 힘을 다룰 수 있습니다.',
 scene:'연습 중 틀린 한 문제를 보고도 전체 성과가 흔들리는 것처럼 받아들이는 상황을 떠올려 보세요. 그 문제를 점수에서 잠시 떼어 내고 어느 단계에서 풀이가 달라졌는지 보면, 실패는 다음 행동을 정하는 정보가 됩니다.',
 trap:'모든 연습을 평가처럼 다루면 새로운 방법을 시도할 여지가 줄어듭니다. 잘하고 싶은 마음을 연습 횟수와 수정 과정에 연결해 주세요.',action:'오늘 공부를 점수 없이 방법을 찾는 연습과, 시간을 정해 확인하는 실전으로 나누세요. 연습 기록에는 틀린 수 대신 고친 과정 한 가지를 남기세요.',childAction:'처음 연습할 때는 점수와 시간을 빼 주세요. 아이가 풀이를 고친 지점을 먼저 짚고, 익숙해진 다음 짧은 실전 과제를 따로 주세요.',observe:'목표를 낮췄는지가 아니라, 틀린 뒤 다시 시도하는 간격이 짧아졌는지 살펴보세요.',strong:['achievement'],stages:['동기','실전','회복']},
 {id:'analysis-with-intuition',when:[['analytical','high'],['intuitive','high']],thesis:'먼저 잡은 전체 그림을 논리로 확인할 때 이해가 단단해집니다',
 opening:'@who의 생각에는 전체 흐름을 먼저 잡는 움직임과, 세부 근거를 나누어 확인하는 움직임이 함께 있습니다. 처음 떠오른 답은 출발점이 되고, 왜 그 답인지 설명하는 과정에서 이해가 정교해집니다.',
 mechanism:'빠르게 감을 잡는 순간과 차근차근 검증하는 순간을 한 번에 끝내려 하면 생각의 순서가 꼬입니다. 먼저 예상한 뒤 근거를 채우는 두 단계로 나누면 직관이 탐색의 방향을 만들고 분석이 그 방향을 점검합니다.',
 scene:'문제를 보고 답의 방향이 떠올랐다면 곧바로 지우거나 확정하지 말고 예상으로 남겨 보세요. 이후 조건을 하나씩 대입해 맞는 부분과 수정할 부분을 나누면, 맞혔을 때도 왜 맞았는지가 남습니다.',
 trap:'첫 느낌을 검증 없이 결론으로 삼거나, 반대로 근거가 완성될 때까지 떠오른 생각을 모두 버리면 두 강점이 따로 움직입니다.',action:'답을 예상하는 칸과 근거를 확인하는 칸을 나누세요. 마지막에는 처음 예상에서 무엇을 바꿨는지 한 줄로 정리하세요.',childAction:'아이의 첫 생각을 먼저 듣고 “어떤 부분을 보고 그랬어?”라고 이어 주세요. 다른 조건을 함께 확인한 뒤 생각을 바꿀 기회도 주세요.',observe:'정답 여부와 함께 처음 예상과 최종 설명 사이에 근거가 얼마나 더해졌는지 보세요.',strong:['analytical','intuitive'],stages:['이해','표현','실전']},
 {id:'planning-with-flexibility',when:[['planning','high'],['adaptive_flexibility','high']],thesis:'계획을 세우는 힘에 방법을 바꾸는 여유가 함께 있습니다',
 opening:'@who은 공부의 순서를 정해 방향을 잡고, 상황이 달라지면 가능한 방법을 다시 찾습니다. 계획은 지켜야 할 모양이면서 동시에 현재 상황을 살펴보는 기준이 됩니다. 준비와 조정이 함께 작동할 때 배움을 안정적으로 이어 갑니다.',
 mechanism:'계획을 세우는 성향과 방법을 바꾸는 유연함은 서로 보완합니다. 다만 수정할 때마다 목표까지 함께 바꾸면 무엇을 끝냈는지 흐려집니다. 끝낼 결과는 남겨 두고 순서·분량·도구를 조절하는 방식으로 두 힘을 연결하는 것이 핵심입니다.',
 scene:'예상보다 어려운 단원을 만났을 때 전체 계획을 포기하기보다 오늘 확인할 핵심 개념 하나를 남기고 연습량을 조절하는 장면입니다. 계획을 고치는 이유와 유지할 목표를 함께 적으면 수정에도 방향이 생깁니다.',
 trap:'방법을 유연하게 바꾸는 것과 목표를 계속 새로 정하는 것을 구분해야 합니다. 수정 뒤에도 남는 결과가 있어야 계획이 축적됩니다.',action:'오늘의 필수 결과 한 가지와 조절 가능한 활동 두 가지를 나누세요. 일정이 달라지면 활동부터 조정하고 결과는 마지막에 확인하세요.',childAction:'오늘 꼭 남길 결과를 하나 정하고, 활동 순서는 아이와 조절해 주세요. 계획을 바꿨다면 무엇을 지켰는지도 함께 짚어 주세요.',observe:'계획을 그대로 지킨 날뿐 아니라, 계획을 바꾼 날에도 핵심 결과가 남았는지 확인하세요.',strong:['planning','adaptive_flexibility'],stages:['시작','연습','마무리']},
 {id:'autonomy-and-interference',when:[['independence','high'],['control_sensitivity','high']],thesis:'도움의 양보다 결정권을 어디에 두는지가 중요합니다',
 opening:'@who은 자신의 판단으로 방법을 고를 때 과제를 자기 일로 받아들입니다. 동시에 세부 행동에 대한 간섭에는 민감하게 반응합니다. 좋은 방법을 알려주려는 도움도 선택할 여지가 없으면 공부 내용보다 지시 방식에 마음이 걸립니다.',
 mechanism:'자기 방식을 지키려는 마음과 통제에 대한 민감함이 같은 방향으로 작용합니다. 이때 설득의 말을 더하는 것보다 무엇을 스스로 결정할 수 있는지 분명히 하는 편이 효과적입니다. 책임질 결과와 선택할 과정을 함께 정해야 주도권이 마무리로 이어집니다.',
 scene:'풀이 순서를 고쳐 주는 말에 흐름이 끊기는 상황이라면 먼저 어떤 방법을 시도하려 했는지 설명할 자리를 주세요. 스스로 선택한 방법으로 한 번 해 본 뒤 결과를 비교하면 조언을 검토할 공간이 생깁니다.',
 trap:'공부해야 할 이유를 둘러싼 대화가 누가 결정하는지를 둘러싼 실랑이로 바뀌는 지점입니다. 합의한 기준으로 돌아와 과정을 선택하게 해야 합니다.',action:'마감과 결과 기준을 먼저 정하고 풀이 순서는 직접 선택하세요. 다른 방법은 한 번 시도한 뒤 비교 대상으로 사용하세요.',childAction:'“이렇게 해”라고 고치기 전에 아이가 고른 방법을 한 번 설명하게 해 주세요. 끝나는 기준을 합의하고, 결과를 본 뒤 다른 방법과 비교해 주세요.',observe:'지시 횟수보다 스스로 선택한 과제를 끝까지 마친 경험이 늘어나는지 살펴보세요.',strong:['independence'],stages:['시작','연습','마무리']},
 {id:'expression-and-depth',when:[['depth_orientation','high'],['verbal_expression','high']],thesis:'깊이 생각한 것을 표현할 때 배움의 빈틈이 드러납니다',
 opening:'@who은 한 주제를 오래 들여다보는 힘과, 생각을 말과 글로 펼치는 통로를 함께 갖고 있습니다. 안에서 충분히 생각한 내용을 밖으로 꺼내면 어디까지 이해했는지 윤곽이 선명해집니다.',
 mechanism:'혼자 생각하는 시간과 표현하는 시간은 서로 다른 역할을 합니다. 생각만 이어 가면 연결이 빠진 부분을 놓치고, 표현만 이어 가면 처음의 질문을 충분히 다루지 못합니다. 탐구한 뒤 설명하고, 설명하다 막힌 부분을 다시 탐구하는 순환이 두 힘을 이어 줍니다.',
 scene:'한 개념을 읽은 뒤 처음 배우는 사람에게 설명한다고 생각해 보세요. 말이 막히는 곳에서 자료를 다시 확인하면 다음 탐구의 목적이 생깁니다. 매끄럽게 말하는 것보다 빠진 연결을 찾아내는 일이 이 연습의 핵심입니다.',
 trap:'읽은 양과 설명한 양만 늘리고 처음의 질문을 해결했는지 확인하지 않으면 배움의 초점이 흐려집니다.',action:'공부 전 질문 하나를 적고, 공부 뒤 그 질문에 세 문장으로 답하세요. 설명에서 비어 있는 한 부분만 다시 찾아보세요.',childAction:'아이에게 궁금한 것 하나를 고르게 하고, 알아본 뒤 자기 말이나 그림으로 설명하게 해 주세요. 막힌 부분은 함께 다시 찾아보세요.',observe:'처음 질문에 대한 설명이 전보다 구체적이고 간결해졌는지 비교하세요.',strong:['verbal_expression','depth_orientation'],stages:['이해','표현','회복']},
 {id:'mastery-with-persistence',when:[['mastery','high'],['persistence','high']],thesis:'조금씩 나아지는 감각이 오래 이어 가는 힘이 됩니다',
 opening:'@who은 실력이 달라지는 과정에서 배울 이유를 찾고, 흥미가 줄어든 뒤에도 과제를 이어 가는 힘을 보탭니다. 눈에 띄는 한 번의 성과보다 어제 막혔던 부분이 오늘 풀리는 경험이 공부의 기반을 만듭니다.',
 mechanism:'숙달을 향한 동기와 지속성이 서로 뒷받침합니다. 이 강점을 살리려면 단순히 시간을 오래 쓰는 것과 방법을 개선하는 것을 구분해야 합니다. 오래 붙잡은 과제에서 무엇이 달라졌는지 확인할 때 반복이 경험으로 쌓입니다.',
 scene:'틀렸던 문제를 다시 풀 때 답을 기억해 맞히는 데서 끝내지 않고, 이전 풀이와 달라진 한 단계를 찾아보는 장면입니다. 같은 공부 시간 안에서도 개선한 부분이 보이면 다음 연습의 목적이 선명해집니다.',
 trap:'꾸준히 했다는 사실만으로 방법까지 적절했다고 여기면 같은 막힘을 오래 반복하게 됩니다. 지속할 것은 목표이고 점검할 것은 접근 방법입니다.',action:'복습할 때 이전 풀이와 달라진 한 단계를 기록하세요. 같은 오류가 반복되면 횟수를 늘리기 전에 풀이 순서를 바꾸세요.',childAction:'아이가 꾸준히 했다는 점과 실제로 달라진 점을 함께 짚어 주세요. 같은 실수가 반복되면 더 하게 하기 전에 접근 방법을 함께 바꿔 주세요.',observe:'학습 시간과 함께 도움 없이 해결한 단계가 늘었는지 확인하세요.',strong:['mastery','persistence'],stages:['연습','마무리','회복']}
];
